<script setup lang="ts">
import {usePageActivity} from '../page-activity';
const listLoaded=ref(false);
const pageActive=usePageActivity();
import Modal from '../components/Modal.vue';
import MetricCard from '../components/MetricCard.vue';
import EmptyState from '../components/EmptyState.vue';
import Pagination from '../components/Pagination.vue';
import {confirmOperation} from '../modal';

import { useScopedRefresh } from '../scoped-refresh';
import { useFeedback } from '../feedback';
import { markDirty } from '../workspace';
import { formatBeijing,employeeLabel } from '../presentation';
import { ref, onMounted } from 'vue';
import { me } from '../api';
import { courseApi, errorText, tag, type LeavePage, type LeaveSummary, type Leave } from '../course-api';
const props=withDefaults(defineProps<{approvalMode?:boolean}>(),{approvalMode:false});
const personal=ref<LeaveSummary|null>(null),filters=ref({leave_type:'',status:'',submitted_from:'',submitted_to:''});
const leaveOpen=ref(false),detail=ref<Leave|null>(null),pageSize=ref(20);
const items=ref<Leave[]>([]), scope=ref<'mine'|'approval'>(props.approvalMode?'approval':'mine'), manager=ref(false), page=ref(1), total=ref(0), busy=ref(false), error=ref(''), notice=ref('');
const blankLeave=()=>({start_date:'',end_date:'',leave_type:'ANNUAL',reason:''});
const form=ref(blankLeave()), selected=ref<Leave|null>(null), opinion=ref('');
const types:Record<string,string>={ANNUAL:'年假',SICK:'病假',PERSONAL:'事假',OTHER:'其他'};
const statuses:Record<string,string>={PENDING:'待审批',APPROVED:'已批准',REJECTED:'已驳回',CANCELLED:'已取消'};
let loadGeneration=0;
async function load(strict=false,preserve=false){const mine=++loadGeneration;busy.value=true;error.value='';try{const query=new URLSearchParams({scope:scope.value,page:String(page.value),page_size:String(pageSize.value)});if(!props.approvalMode)for(const [key,value] of Object.entries(filters.value))if(value)query.set(key,value);const result=await courseApi<LeavePage>(`/leaves?${query}`);if(!props.approvalMode&&!result.summary)throw new Error('暂时无法加载请假统计，请重试');if(mine===loadGeneration){items.value=result.items;total.value=result.total;listLoaded.value=true;personal.value=result.summary||null;if(detail.value&&!result.items.some(row=>row.id===detail.value?.id))detail.value=null;
 if(!preserve||selected.value&&!result.items.some(row=>row.id===selected.value?.id&&row.status==='PENDING')){selected.value=null;opinion.value='';markDirty('/approvals',false,'decision');}}}catch(e){if(mine===loadGeneration){items.value=[];total.value=0;personal.value=null;error.value=errorText(e);}if(strict===true)throw e;}finally{if(mine===loadGeneration)busy.value=false;}}
async function create(){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await courseApi('/leaves','POST',form.value);leaveOpen.value=false;markDirty('/leaves',false,'leave');notice.value='请假申请已提交';form.value=blankLeave();scope.value='mine';page.value=1;await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function cancel(row:Leave){await confirmOperation({title:'撤销请假申请',message:`确认取消 ${row.start_date} 至 ${row.end_date} 的待审批申请？`,confirmLabel:'确认撤销',danger:true},async()=>{busy.value=true;error.value='';notice.value='';try{await courseApi(`/leaves/${encodeURIComponent(row.id)}/cancel`,'POST',{},tag(row));notice.value='申请已取消';await load();}finally{busy.value=false;}});}
async function decide(status:'APPROVED'|'REJECTED'){if(busy.value)return;if(!selected.value)return;busy.value=true;error.value='';notice.value='';try{await courseApi(`/leaves/${encodeURIComponent(selected.value.id)}/decision`,'POST',{status,opinion:opinion.value},tag(selected.value));markDirty('/approvals',false,'decision');notice.value='审批结果已保存';opinion.value='';await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
onMounted(async()=>{try{manager.value=(await me()).roles.includes('MANAGER');await load();}catch(e){error.value=errorText(e);}});
const {scopeLocked,scopeFailure,retryScope}=useScopedRefresh(()=>load(true,true));
function query(){page.value=1;void load();}
function resetFilters(){filters.value={leave_type:'',status:'',submitted_from:'',submitted_to:''};query();}
function openLeave(){form.value=blankLeave();error.value='';leaveOpen.value=true;}
function closeLeave(){form.value=blankLeave();leaveOpen.value=false;}
useFeedback(notice,error,props.approvalMode?'/approvals':'/leaves');
</script>
<template><div class="business-page leaves-page"><p v-if="scopeLocked" class="verification" role="status">{{scopeFailure||'正在加载…'}}<button v-if="scopeFailure" @click="retryScope">重试</button></p><main v-show="!scopeLocked"><div class="section-heading"><h1>{{props.approvalMode?'直属部门审批':'请假管理'}}</h1><button v-if="!props.approvalMode" @click="openLeave">申请请假</button></div><p v-if="error" class="error feedback" role="alert">{{error}}</p><p v-if="notice" class="success feedback" role="status">{{notice}}</p>
<p v-if="!props.approvalMode" class="muted leave-intro">查看和管理我的请假申请记录。</p>
<div v-if="!props.approvalMode&&personal&&!error" class="metric-grid leave-metrics" :aria-busy="busy"><MetricCard label="本月申请次数" :value="personal.submitted_this_month" icon="calendar"/><MetricCard label="待审批" :value="personal.pending" icon="clock" tone="amber"/><MetricCard label="已批准" :value="personal.approved" icon="check" tone="green"/><MetricCard label="已驳回" :value="personal.rejected" icon="cross" tone="red"/></div>
<section v-if="!props.approvalMode" class="card leave-query"><form class="search-row" @submit.prevent="query"><label>请假类型<select aria-label="请假类型" v-model="filters.leave_type"><option value="">全部</option><option v-for="(label,key) in types" :key="key" :value="key">{{label}}</option></select></label><div class="date-filter"><span>申请时间</span><div><input aria-label="申请开始日期" v-model="filters.submitted_from" type="date"><span>至</span><input aria-label="申请结束日期" v-model="filters.submitted_to" type="date" :min="filters.submitted_from||undefined"></div></div><label>状态<select aria-label="请假状态" v-model="filters.status"><option value="">全部</option><option v-for="(label,key) in statuses" :key="key" :value="key">{{label}}</option></select></label><button :disabled="busy">查询</button><button type="button" class="secondary" :disabled="busy" @click="resetFilters">重置</button></form></section>
<Modal v-if="!props.approvalMode&&leaveOpen" title="申请请假" scope="leave" :busy="busy" :error="error" :concealed="scopeLocked" @retry="retryScope" @close="closeLeave"><form data-dirty-scope="leave" @submit.prevent="create"><fieldset :disabled="busy"><div class="form-columns"><label>起始日期<input v-model="form.start_date" type="date" required></label><label>结束日期<input v-model="form.end_date" type="date" required :min="form.start_date"></label><label>类型<select aria-label="类型" v-model="form.leave_type"><option v-for="(label,key) in types" :key="key" :value="key">{{label}}</option></select></label><label>理由<textarea v-model="form.reason" required maxlength="500" rows="3"></textarea></label></div><p class="muted">仅计算工作日；与待审或已批准的工作日重叠将被拒绝。</p><div class="form-actions"><button type="button" class="secondary" data-modal-cancel>取消</button><button>提交申请</button></div></fieldset></form></Modal>
<section class="card"><div class="section-heading"><h2>{{scope==='mine'?'我的请假记录':'直属部门审批'}}</h2><router-link v-if="manager&&!props.approvalMode" to="/approvals">直属部门审批</router-link><router-link v-if="props.approvalMode" to="/leaves">本人请假</router-link><button class="secondary" :disabled="busy" @click="load()">刷新</button></div><p v-if="busy||!listLoaded&&!error" role="status">正在加载…</p><EmptyState v-else-if="listLoaded&&!error&&!items.length" :text="props.approvalMode?'暂无待处理或历史审批记录':'暂无请假记录'"/>
<div v-else-if="listLoaded&&!error" class="table-scroll"><table><thead><tr><th v-if="props.approvalMode">员工</th><th v-else>申请时间</th><th>请假类型</th><th>开始日期</th><th>结束日期</th><th>请假事由</th><th>状态</th><th>审批留痕</th><th>操作</th></tr></thead><tbody><tr v-for="row in items" :key="row.id"><td v-if="props.approvalMode">{{employeeLabel(row)}}</td><td v-else>{{formatBeijing(row.created_at)}}</td><td>{{types[row.leave_type]}}</td><td>{{row.start_date}}</td><td>{{row.end_date}}</td><td>{{row.reason}}</td><td><span :class="['leave-status',row.status.toLowerCase()]">{{statuses[row.status]}}</span></td><td>{{row.opinion||'—'}}<br>{{row.decided_by_username||''}}<br><small>{{formatBeijing(row.decided_at)}}</small></td><td><button class="text-button" @click="detail=row">详情</button><button v-if="row.status==='PENDING'&&scope==='mine'" class="text-button" :disabled="busy" @click="cancel(row)">取消申请</button><button v-if="row.status==='PENDING'&&scope==='approval'" class="text-button" :disabled="busy" @click="selected=row;opinion=''">处理审批</button></td></tr></tbody></table></div><Pagination :page="page" :page-size="pageSize" :total="total" :busy="busy" @page="page=$event;load()" @size="pageSize=$event;page=1;load()"/>
<Modal v-if="selected" title="请假审批" scope="decision" :busy="busy" :error="error" :concealed="scopeLocked" @retry="retryScope" @close="selected=null;opinion=''"><dl><dt>员工</dt><dd>{{employeeLabel(selected)}}</dd><dt>类型 / 理由</dt><dd>{{types[selected.leave_type]}} · {{selected.reason}}</dd></dl><form class="decision-form" data-dirty-scope="decision" @submit.prevent="decide('APPROVED')"><h3>处理 {{selected.start_date}} 至 {{selected.end_date}} 的申请</h3><label>审批意见<textarea v-model="opinion" required maxlength="500" rows="3"></textarea></label><div class="form-actions"><button :disabled="busy">批准</button><button type="button" class="secondary" :disabled="busy||!opinion.trim()" @click="decide('REJECTED')">驳回</button><button type="button" class="secondary" data-modal-cancel>关闭</button></div></form></Modal>
</section><Modal v-if="detail" title="请假详情" :track-changes="false" :concealed="scopeLocked" @retry="retryScope" @close="detail=null"><dl><dt>员工</dt><dd>{{employeeLabel(detail)}}</dd><dt>日期</dt><dd>{{detail.start_date}} 至 {{detail.end_date}}</dd><dt>类型 / 状态</dt><dd>{{types[detail.leave_type]}} · {{statuses[detail.status]}}</dd><dt>理由</dt><dd>{{detail.reason}}</dd><dt>审批意见</dt><dd>{{detail.opinion||'—'}}</dd><dt>操作账号 / 北京时间</dt><dd>{{detail.decided_by_username||'—'}} · {{formatBeijing(detail.decided_at)}}</dd></dl></Modal></main></div></template>
